      std::string block, def = kDefaultDrops; size_t a = def.find("# smoke_seconds:"), b = a == std::string::npos ? a : def.find(last, a);
      if (a != std::string::npos && b != std::string::npos) block = def.substr(a, b + strlen(last) - a);
